ALTER TABLE public.interests DROP CONSTRAINT IF EXISTS interests_sender_fkey;
ALTER TABLE public.interests ADD CONSTRAINT interests_sender_fkey FOREIGN KEY (sender_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
