ALTER TABLE public.interests ADD CONSTRAINT interests_recipient_fkey FOREIGN KEY (recipient_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
ALTER TABLE public.copilots DROP CONSTRAINT IF EXISTS copilots_candidate_fkey;
ALTER TABLE public.copilots ADD CONSTRAINT copilots_candidate_fkey FOREIGN KEY (candidate_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
ALTER TABLE public.copilots DROP CONSTRAINT IF EXISTS copilots_user_fkey;
ALTER TABLE public.copilots ADD CONSTRAINT copilots_user_fkey FOREIGN KEY (copilot_user_id) REFERENCES public.profiles(id) ON DELETE SET NULL;
ALTER TABLE public.copilot_recommendations DROP CONSTRAINT IF EXISTS copilot_rec_candidate_fkey;
