ALTER TABLE public.copilot_recommendations ADD CONSTRAINT copilot_rec_profile_fkey FOREIGN KEY (recommended_profile_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
ALTER TABLE public.reports DROP CONSTRAINT IF EXISTS reports_reporter_fkey;
ALTER TABLE public.reports ADD CONSTRAINT reports_reporter_fkey FOREIGN KEY (reporter_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
ALTER TABLE public.reports DROP CONSTRAINT IF EXISTS reports_reported_fkey;
ALTER TABLE public.reports ADD CONSTRAINT reports_reported_fkey FOREIGN KEY (reported_profile_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
