ALTER TABLE public.notifications ADD CONSTRAINT notifications_user_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
ALTER TABLE public.saved_profiles DROP CONSTRAINT IF EXISTS saved_profiles_user_fkey;
ALTER TABLE public.saved_profiles ADD CONSTRAINT saved_profiles_user_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
